_FALLBACK_SRC = '# Exact action format: "[(from_node, to_node, count), ...]"\n# Payout: revenue_p = sum of node_value[i] over all nodes i that player p owns.\n# Upkeep: upkeep_p = UPKEEP * (UNITS_PER_PLAYER - units of p on its own base).\n# Profit is revenue minus upkeep. Ownership persists without a garrison.\n# Capture requires a strict majority at two consecutive turn ends.\n#\n# Conservative capture-and-return policy: use one unit per uncontested target,\n# budget the entire trip home, and leave unused units at their free home base.\n\nimport heapq\n\nTIME_BUDGET = 0.25\nN_TURNS = 80\nUNITS_PER_PLAYER = 20\nUPKEEP = 2.0\n\n\ndef payout(values, owned, units_on_base):\n    """The specification\'s per-turn profit, without approximations."""\n    revenue = sum(value for value, owner in zip(values, owned) if owner)\n    upkeep = UPKEEP * (UNITS_PER_PLAYER - units_on_base)\n    return float(revenue - upkeep)\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    lengths = {}\n    for u, v, length in edges:\n        u, v, length = int(u), int(v), int(length)\n        adjacency[u].append((v, length))\n        adjacency[v].append((u, length))\n        lengths[u, v] = length\n        lengths[v, u] = length\n    for row in adjacency:\n        row.sort()\n\n    distances = []\n    for source in range(n):\n        distance = [10**9] * n\n        distance[source] = 0\n        queue = [(0, source)]\n        while queue:\n            cost, u = heapq.heappop(queue)\n            if cost != distance[u]:\n                continue\n            for v, length in adjacency[u]:\n                candidate = cost + length\n                if candidate < distance[v]:\n                    distance[v] = candidate\n                    heapq.heappush(queue, (candidate, v))\n        distances.append(distance)\n\n    next_hop = [[-1] * n for _ in range(n)]\n    for source in range(n):\n        for target in range(n):\n            if source != target:\n                for neighbour, length in adjacency[source]:\n                    if length + distances[neighbour][target] == distances[source][target]:\n                        next_hop[source][target] = neighbour\n                        break\n    return distances, next_hop, lengths\n\n\ndef make_plan(obs, distances, next_hop):\n    n = int(obs["n_nodes"])\n    turn = int(obs["turn"])\n    remaining = max(0, N_TURNS - turn)\n    home = int(obs["player_base"])\n    enemy_home = int(obs["opponent_base"])\n    values = obs["node_value"]\n    own = obs["player_owned"]\n    enemy_owned = obs["opponent_owned"]\n    units = obs["player_units"]\n    enemies = obs["opponent_units"]\n    leads = obs["player_lead_turns"]\n\n    # Each source is either a start-of-turn node or an irrevocable transit.\n    # Transits reserve work too, preventing duplicate deployments.\n    sources = []\n    for node in range(n):\n        if units[node] > 0:\n            sources.append([node, 0, int(units[node]), True])\n    for _, destination, count, arrival in obs.get("player_transits", []):\n        if count > 0:\n            sources.append([\n                int(destination), max(0, int(arrival) - turn),\n                int(count), False\n            ])\n\n    threatened = [bool(enemies[v]) for v in range(n)]\n    for _, destination, count, _ in obs.get("opponent_transits", []):\n        if count > 0:\n            threatened[int(destination)] = True\n\n    candidates = []\n    for target in range(n):\n        if target in (home, enemy_home) or own[target] or threatened[target]:\n            continue\n        if values[target] <= 0:\n            continue\n        for index, (source, delay, count, movable) in enumerate(sources):\n            travel = delay + distances[source][target]\n            # Already leading at the target requires only one more turn.\n            already_leading = (\n                movable and source == target and leads[target] >= 1\n            )\n            capture_delay = 0 if already_leading else max(1, travel)\n            earning_turns = max(0, remaining - capture_delay)\n\n            # Budget ALL future away time through capture and return, not\n            # merely the outbound leg. An extra turn is a safety allowance.\n            away_budget = travel + distances[target][home] + 2\n            cost = UPKEEP * away_budget\n            gain = values[target] * earning_turns\n            # Capturing an enemy-owned node also denies its entire payout.\n            # No proportional sharing exists in this game.\n            denial = gain if enemy_owned[target] else 0\n\n            # Require positive own economics even before counting denial.\n            if gain <= cost + 8.0:\n                continue\n            if travel + 1 >= remaining and not already_leading:\n                continue\n\n            # Nearest jobs first; capturing a lead already in progress\n            # takes precedence. Value and denial only break close ties.\n            priority = (\n                0 if already_leading else 1,\n                travel,\n                -(gain + denial - cost),\n                target,\n                index,\n            )\n            candidates.append((priority, index, target))\n\n    candidates.sort()\n    assigned = set()\n    plan = {}\n    for _, index, target in candidates:\n        source, delay, count, movable = sources[index]\n        if count <= 0 or target in assigned:\n            continue\n        assigned.add(target)\n        sources[index][2] -= 1\n        if movable and source != target:\n            hop = next_hop[source][target]\n            if hop >= 0:\n                plan[source, hop] = plan.get((source, hop), 0) + 1\n\n    # Units not assigned to a profitable capture go home immediately.\n    # Captured nodes continue paying after the unit leaves.\n    for source, delay, count, movable in sources:\n        if movable and count > 0 and source != home:\n            hop = next_hop[source][home]\n            if hop >= 0:\n                plan[source, hop] = plan.get((source, hop), 0) + count\n    return plan\n\n\ndef legal_action(plan, start_units, lengths, n):\n    available = [int(count) for count in start_units]\n    action = []\n    for (source, target), requested in sorted(plan.items()):\n        source, target = int(source), int(target)\n        if not (0 <= source < n and 0 <= target < n):\n            continue\n        if source == target or (source, target) not in lengths:\n            continue\n        count = min(max(0, int(requested)), available[source])\n        if count > 0:\n            action.append((int(source), int(target), int(count)))\n            available[source] -= count\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = int(player_id)\n        self.map_key = None\n        self.map_data = None\n\n    def act(self, obs):\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0 or not obs.get("player_units"):\n            return []\n        edges = obs.get("edges", [])\n        key = (n, tuple(tuple(edge) for edge in edges))\n        if self.map_key != key:\n            self.map_data = preprocess_map(n, edges)\n            self.map_key = key\n        distances, next_hop, lengths = self.map_data\n        plan = make_plan(obs, distances, next_hop)\n        return legal_action(plan, obs["player_units"], lengths, n)\n'
